  1	/**
  2	 * WP-009: New Test Suite — Repository Scope Integration Tests
  3	 *
  4	 * 26 test cases covering repository scope functionality across two layers:
  5	 *
  6	 * Storage layer (KnowledgeStoreManager) — 16 cases:
  7	 *   - repositoryStorePath path generation and reserved-name guard
  8	 *   - addInsight with repository scope (success and missing-repository_name error)
  9	 *   - readRepositoryStore empty and populated
 10	 *   - listInsights unfiltered, scope-filtered, and name-filtered
 11	 *   - searchInsights with repository_name
 12	 *   - updateInsight and deleteInsight with repository scope
 13	 *   - moveInsight global→repo, repo→repo, and same-name rejection
 14	 *   - origin_plan preservation through add, update, and move
 15	 *
 16	 * GUI REST handlers (gui/api-knowledge.ts) — 10 cases:
 17	 *   - handleListKnowledge with repository_name
 18	 *   - handleUpdateKnowledge with repository scope and repository_name
 19	 *   - handleDeleteKnowledge with repository scope (success and missing repository_name)
 20	 *   - handlePromoteKnowledge from repository (success) and from global (rejection)
 21	 *   - handleMoveKnowledge global→repo, repo→repo same-name rejection,
 22	 *     missing target_repository_name rejection
 23	 *   - scope: 'project' rejection by all handlers
 24	 *
 25	 * Uses real temp directories (mkdtemp/rm) and KnowledgeStoreManager — no mocks.
 26	 * Follows the pattern established in tests/gui/knowledge-api.test.ts.
 27	 */
 28	
 29	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 30	import { mkdtemp, rm } from 'fs/promises';
 31	import { join } from 'path';
 32	import { tmpdir } from 'os';
 33	
 34	import {
 35	  handleListKnowledge,
 36	  handleUpdateKnowledge,
 37	  handleDeleteKnowledge,
 38	  handlePromoteKnowledge,
 39	  handleMoveKnowledge,
 40	  ApiError,
 41	} from '../../gui/api-knowledge.js';
 42	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
 43	import type { Insight } from '../../src/schema/knowledge.js';
 44	
 45	// ---------------------------------------------------------------------------
 46	// Helpers
 47	// ---------------------------------------------------------------------------
 48	
 49	/** Build a minimal valid insight input (no id). */
 50	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
 51	  return {
 52	    scope: 'global',
 53	    title: 'Default title',
 54	    content: 'Default content',
 55	    category: 'general',
 56	    tags: [],
 57	    source: 'test',
 58	    created_at: '2026-01-01T00:00:00Z',
 59	    confidence: 0.8,
 60	    ...overrides,
 61	  };
 62	}
 63	
 64	// ---------------------------------------------------------------------------
 65	// Storage layer — repositoryStorePath
 66	// ---------------------------------------------------------------------------
 67	
 68	describe('KnowledgeStoreManager.repositoryStorePath', () => {
 69	  let ledgerRoot: string;
 70	  let manager: KnowledgeStoreManager;
 71	
 72	  beforeEach(async () => {
 73	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-path-'));
 74	    manager = new KnowledgeStoreManager(ledgerRoot);
 75	  });
 76	
 77	  afterEach(async () => {
 78	    await rm(ledgerRoot, { recursive: true, force: true });
 79	  });
 80	
 81	  it("returns {knowledgeDir}/{repoName}-insights.json for a valid repository name", () => {
 82	    const storePath = manager.repositoryStorePath('hcp-editor');
 83	    const expected = join(manager.knowledgeDir(), 'hcp-editor-insights.json');
 84	    expect(storePath).toBe(expected);
 85	  });
 86	
 87	  it("throws for the reserved name 'global'", () => {
 88	    expect(() => manager.repositoryStorePath('global')).toThrow(
 89	      "'global' is a reserved name and cannot be used as a repository name."
 90	    );
 91	  });
 92	});
 93	
 94	// ---------------------------------------------------------------------------
 95	// Storage layer — addInsight (repository scope)
 96	// ---------------------------------------------------------------------------
 97	
 98	describe('KnowledgeStoreManager.addInsight — repository scope', () => {
 99	  let ledgerRoot: string;
100	  let manager: KnowledgeStoreManager;

101	
102	  beforeEach(async () => {
103	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-add-'));
104	    manager = new KnowledgeStoreManager(ledgerRoot);
105	  });
106	
107	  afterEach(async () => {
108	    await rm(ledgerRoot, { recursive: true, force: true });
109	  });
110	
111	  it('creates repository store file with correct fields including origin_plan', async () => {
112	    const insight = await manager.addInsight(
113	      makeInsightInput({
114	        scope: 'repository',
115	        repository_name: 'hcp-editor',
116	        origin_plan: 'my-plan',
117	        title: 'Codebase insight',
118	      })
119	    );
120	
121	    expect(insight.scope).toBe('repository');
122	    expect(insight.repository_name).toBe('hcp-editor');
123	    expect(insight.origin_plan).toBe('my-plan');
124	    expect(insight.title).toBe('Codebase insight');
125	    expect(insight.id).toBeTypeOf('number');
126	    expect(insight.id).toBeGreaterThan(0);
127	
128	    // Verify the file was written in the correct location
129	    const store = await manager.readRepositoryStore('hcp-editor');
130	    expect(store.insights).toHaveLength(1);
131	    expect(store.insights[0]!.title).toBe('Codebase insight');
132	  });
133	
134	  it('throws when repository_name is absent for repository-scoped insight', async () => {
135	    await expect(
136	      manager.addInsight(
137	        makeInsightInput({ scope: 'repository' /* no repository_name */ })
138	      )
139	    ).rejects.toThrow('repository_name is required for repository-scoped insights');
140	  });
141	});
142	
143	// ---------------------------------------------------------------------------
144	// Storage layer — readRepositoryStore
145	// ---------------------------------------------------------------------------
146	
147	describe('KnowledgeStoreManager.readRepositoryStore', () => {
148	  let ledgerRoot: string;
149	  let manager: KnowledgeStoreManager;
150	
151	  beforeEach(async () => {
152	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-read-'));
153	    manager = new KnowledgeStoreManager(ledgerRoot);
154	  });
155	
156	  afterEach(async () => {
157	    await rm(ledgerRoot, { recursive: true, force: true });
158	  });
159	
160	  it('returns empty store when repository file does not exist', async () => {
161	    const store = await manager.readRepositoryStore('hcp-editor');
162	    expect(store.insights).toEqual([]);
163	    expect(store.next_id).toBe(1);
164	  });
165	
166	  it('returns stored insights after addInsight', async () => {
167	    await manager.addInsight(
168	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'First' })
169	    );
170	    await manager.addInsight(
171	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'Second' })
172	    );
173	
174	    const store = await manager.readRepositoryStore('hcp-editor');
175	    expect(store.insights).toHaveLength(2);
176	    const titles = store.insights.map((i) => i.title);
177	    expect(titles).toContain('First');
178	    expect(titles).toContain('Second');
179	  });
180	});
181	
182	// ---------------------------------------------------------------------------
183	// Storage layer — listInsights (scope and repository_name filtering)
184	// ---------------------------------------------------------------------------
185	
186	describe('KnowledgeStoreManager.listInsights — repository scope filtering', () => {
187	  let ledgerRoot: string;
188	  let manager: KnowledgeStoreManager;
189	
190	  beforeEach(async () => {
191	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-list-'));
192	    manager = new KnowledgeStoreManager(ledgerRoot);
193	  });
194	
195	  afterEach(async () => {
196	    await rm(ledgerRoot, { recursive: true, force: true });
197	  });
198	
199	  it('no filters returns global + all repository insights', async () => {
200	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
201	    await manager.addInsight(
202	      makeInsightInput({ scope: 'repository', repository_name: 'alpha', title: 'Alpha insight' })
203	    );
204	    await manager.addInsight(
205	      makeInsightInput({ scope: 'repository', repository_name: 'beta', title: 'Beta insight' })
206	    );
207	
208	    const results = await manager.listInsights({});
209	    expect(results).toHaveLength(3);
210	    const titles = results.map((i) => i.title);
211	    expect(titles).toContain('Global');
212	    expect(titles).toContain('Alpha insight');
213	    expect(titles).toContain('Beta insight');
214	  });
215	
216	  it('scope:repository returns only repository-scoped insights', async () => {
217	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
218	    await manager.addInsight(
219	      makeInsightInput({ scope: 'repository', repository_name: 'alpha', title: 'Alpha' })
220	    );
221	    await manager.addInsight(
222	      makeInsightInput({ scope: 'repository', repository_name: 'beta', title: 'Beta' })
223	    );
224	
225	    const results = await manager.listInsights({ scope: 'repository' });
226	    expect(results).toHaveLength(2);
227	    expect(results.every((i) => i.scope === 'repository')).toBe(true);
228	  });
229	
230	  it('scope:repository + repository_name narrows to one store', async () => {
231	    await manager.addInsight(
232	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'HCP insight' })
233	    );
234	    await manager.addInsight(
235	      makeInsightInput({ scope: 'repository', repository_name: 'other-repo', title: 'Other' })
236	    );
237	
238	    const results = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
239	    expect(results).toHaveLength(1);
240	    expect(results[0]!.title).toBe('HCP insight');
241	    expect(results[0]!.repository_name).toBe('hcp-editor');
242	  });
243	});
244	
245	// ---------------------------------------------------------------------------
246	// Storage layer — searchInsights with repository_name
247	// ---------------------------------------------------------------------------
248	
249	describe('KnowledgeStoreManager.searchInsights — repository_name filter', () => {
250	  let ledgerRoot: string;
251	  let manager: KnowledgeStoreManager;
252	
253	  beforeEach(async () => {
254	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-search-'));
255	    manager = new KnowledgeStoreManager(ledgerRoot);
256	  });
257	
258	  afterEach(async () => {
259	    await rm(ledgerRoot, { recursive: true, force: true });
260	  });
261	
262	  it('searches only the specified repository store', async () => {
263	    await manager.addInsight(
264	      makeInsightInput({
265	        scope: 'repository',
266	        repository_name: 'hcp-editor',
267	        title: 'Atomic writes pattern',
268	        content: 'Use atomic writes for safe file updates.',
269	      })
270	    );
271	    await manager.addInsight(
272	      makeInsightInput({
273	        scope: 'repository',
274	        repository_name: 'other-repo',
275	        title: 'Atomic file operations',
276	        content: 'Other repo content about atomicity.',
277	      })
278	    );
279	
280	    const results = await manager.searchInsights('atomic', { repository_name: 'hcp-editor' });
281	    expect(results).toHaveLength(1);
282	    expect(results[0]!.repository_name).toBe('hcp-editor');
283	    expect(results[0]!.title).toBe('Atomic writes pattern');
284	  });
285	});
286	
287	// ---------------------------------------------------------------------------
288	// Storage layer — updateInsight with repository scope
289	// ---------------------------------------------------------------------------
290	
291	describe('KnowledgeStoreManager.updateInsight — repository scope', () => {
292	  let ledgerRoot: string;
293	  let manager: KnowledgeStoreManager;
294	
295	  beforeEach(async () => {
296	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-update-'));
297	    manager = new KnowledgeStoreManager(ledgerRoot);
298	  });
299	
300	  afterEach(async () => {
301	    await rm(ledgerRoot, { recursive: true, force: true });
302	  });
303	
304	  it('updates insight in repository store correctly', async () => {
305	    const created = await manager.addInsight(
306	      makeInsightInput({
307	        scope: 'repository',
308	        repository_name: 'hcp-editor',
309	        title: 'Original title',
310	      })
311	    );
312	
313	    const updated = await manager.updateInsight(
314	      created.id,
315	      { title: 'Updated title' },
316	      { scope: 'repository', repository_name: 'hcp-editor' }
317	    );
318	
319	    expect(updated.id).toBe(created.id);
320	    expect(updated.title).toBe('Updated title');
321	    expect(updated.scope).toBe('repository');
322	    expect(updated.repository_name).toBe('hcp-editor');
323	  });
324	});
325	
326	// ---------------------------------------------------------------------------
327	// Storage layer — deleteInsight with repository scope
328	// ---------------------------------------------------------------------------
329	
330	describe('KnowledgeStoreManager.deleteInsight — repository scope', () => {
331	  let ledgerRoot: string;
332	  let manager: KnowledgeStoreManager;
333	
334	  beforeEach(async () => {
335	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-delete-'));
336	    manager = new KnowledgeStoreManager(ledgerRoot);
337	  });
338	
339	  afterEach(async () => {
340	    await rm(ledgerRoot, { recursive: true, force: true });
341	  });
342	
343	  it('removes insight from repository store', async () => {
344	    const created = await manager.addInsight(
345	      makeInsightInput({
346	        scope: 'repository',
347	        repository_name: 'hcp-editor',
348	        title: 'To delete',
349	      })
350	    );
351	
352	    await manager.deleteInsight(created.id, { scope: 'repository', repository_name: 'hcp-editor' });
353	
354	    const remaining = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
355	    expect(remaining).toHaveLength(0);
356	  });
357	});
358	
359	// ---------------------------------------------------------------------------
360	// Storage layer — moveInsight (global ↔ repository, repo ↔ repo)
361	// ---------------------------------------------------------------------------
362	
363	describe('KnowledgeStoreManager.moveInsight — repository scope', () => {
364	  let ledgerRoot: string;
365	  let manager: KnowledgeStoreManager;
366	
367	  beforeEach(async () => {
368	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-move-'));
369	    manager = new KnowledgeStoreManager(ledgerRoot);
370	  });
371	
372	  afterEach(async () => {
373	    await rm(ledgerRoot, { recursive: true, force: true });
374	  });
375	
376	  it('moves global insight to repository (global → repository)', async () => {
377	    const global = await manager.addInsight(
378	      makeInsightInput({ scope: 'global', title: 'Will move to repo' })
379	    );
380	
381	    const moved = await manager.moveInsight(
382	      global.id,
383	      { scope: 'global' },
384	      'repository',
385	      'hcp-editor'
386	    );
387	
388	    expect(moved.scope).toBe('repository');
389	    expect(moved.repository_name).toBe('hcp-editor');
390	    expect(moved.title).toBe('Will move to repo');
391	
392	    // Original global insight is removed
393	    const globalInsights = await manager.listInsights({ scope: 'global' });
394	    expect(globalInsights).toHaveLength(0);
395	
396	    // Insight now lives in the repository store
397	    const repoInsights = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
398	    expect(repoInsights).toHaveLength(1);
399	    expect(repoInsights[0]!.title).toBe('Will move to repo');
400	  });

401	
402	  it('moves repository insight to different repository (repository → repository)', async () => {
403	    const original = await manager.addInsight(
404	      makeInsightInput({
405	        scope: 'repository',
406	        repository_name: 'repo-a',
407	        title: 'Cross-repo move',
408	      })
409	    );
410	
411	    const moved = await manager.moveInsight(
412	      original.id,
413	      { scope: 'repository', repository_name: 'repo-a' },
414	      'repository',
415	      'repo-b'
416	    );
417	
418	    expect(moved.scope).toBe('repository');
419	    expect(moved.repository_name).toBe('repo-b');
420	    expect(moved.title).toBe('Cross-repo move');
421	
422	    const repoAInsights = await manager.listInsights({ scope: 'repository', repository_name: 'repo-a' });
423	    expect(repoAInsights).toHaveLength(0);
424	
425	    const repoBInsights = await manager.listInsights({ scope: 'repository', repository_name: 'repo-b' });
426	    expect(repoBInsights).toHaveLength(1);
427	  });
428	
429	  it('throws when moving repository insight to the same repository (identity move)', async () => {
430	    await expect(
431	      manager.moveInsight(
432	        1,
433	        { scope: 'repository', repository_name: 'same-repo' },
434	        'repository',
435	        'same-repo'
436	      )
437	    ).rejects.toThrow();
438	  });
439	});
